define('STUDENT_CARD_SCALE_LOADER', true);
define('STUDENT_CARD_DUPLEX_UI', true);
define('STUDENT_CARD_LAYOUT_FIX', true);
require_once __DIR__ . '/includes/auth.php';
require_once __DIR__ . '/includes/student_card_store.php';
require_login();
require_module('csdl', 'view');

$classes = array_values(array_filter(csdl_classes_all(), static function ($class) {
    return !empty($class['active']) && (!function_exists('can_class') || can_class((string)($class['name'] ?? '')));
}));
usort($classes, static fn($a,$b)=>(int)($a['grade']??0)<=>(int)($b['grade']??0) ?: strnatcasecmp((string)($a['name']??''),(string)($b['name']??'')));
$grades = array_values(array_unique(array_map(static fn($c)=>(string)($c['grade']??''), $classes)));
$year = (string)(csdl_year_current()['label'] ?? SCHOOL_YEAR);
?>
