body{background:#eef3f8;color:#1e293b}.topbar{position:sticky;top:0;z-index:30;background:#0f3b68;color:#fff}.panel{background:#fff;border:1px solid #dbe4ed;border-radius:14px;box-shadow:0 3px 14px rgba(15,23,42,.06)}.step-btn.active{background:#fff;color:#0f3b68}.type-card{border:2px solid #d8e2ec;border-radius:14px;padding:1rem;cursor:pointer;background:#fff}.type-card.active{border-color:#0d6efd;box-shadow:0 0 0 3px rgba(13,110,253,.12)}.theme-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:.45rem}.theme{height:42px;border:2px solid transparent;border-radius:9px;cursor:pointer}.theme.active{border-color:#111827;box-shadow:0 0 0 2px #fff inset}.stage{min-height:610px;display:flex;align-items:flex-start;justify-content:center;padding:20px;overflow:auto;background:#dfe7ef;border-radius:12px}.fold-set{display:flex;align-items:stretch;justify-content:center}.fold-line{width:0;border-left:1px dashed #64748b;position:relative}.fold-line:after{content:'ĐƯỜNG GẤP';position:absolute;top:5mm;left:-4mm;writing-mode:vertical-rl;font-size:6pt;color:#64748b;background:#fff;padding:1mm 0}.card-face{position:relative;overflow:hidden;background:#fff;border:1px solid #94a3b8;color:var(--ink);font-family:Arial,Helvetica,sans-serif}.card-face.vertical{width:54mm;height:86mm}.card-face.horizontal{width:90mm;height:60mm}.card-face.front{border-radius:3mm 0 0 3mm}.card-face.back{border-radius:0 3mm 3mm 0}.decor-top,.decor-bottom{position:absolute;left:0;right:0;background:linear-gradient(135deg,var(--main),var(--second));z-index:0}.vertical .decor-top{height:9mm;top:0;border-radius:0 0 58% 18%}.vertical .decor-bottom{height:7mm;bottom:0;border-radius:55% 18% 0 0}.horizontal .decor-top{height:8mm;top:0;border-radius:0 0 45% 10%}.horizontal .decor-bottom{height:6mm;bottom:0;border-radius:45% 12% 0 0}.face-content{position:relative;z-index:1;height:100%;box-sizing:border-box;text-align:center}.vertical .face-content{padding:3mm 3.3mm 4mm;display:flex;flex-direction:column;align-items:center}.horizontal .face-content{padding:2.8mm 3.5mm 3.5mm}.school-head{display:flex;align-items:center;justify-content:center;gap:2mm;min-height:12mm}.logo{width:11mm;height:11mm;object-fit:contain}.school-lines{line-height:1.12;text-align:left}.agency{font-size:6.4pt;font-weight:700}.school-name{font-size:7.2pt;font-weight:900;max-width:36mm}.title{font-size:13pt;font-weight:900;color:#d71920;white-space:nowrap;line-height:1;margin:1.4mm 0 1.5mm}.vertical .photo{width:22mm;height:29.3mm;object-fit:cover;border:1px solid #94a3b8;border-radius:1.6mm;background:#eef2f7}.student-name{font-size:9.6pt;font-weight:900;color:var(--main);text-transform:uppercase;line-height:1.08;margin-top:1.3mm;max-width:47mm}.student-info{font-size:7.1pt;line-height:1.35;margin-top:1mm}.vertical .front-qr{width:13mm;height:13mm;margin-top:auto;margin-bottom:3mm}.qr img,.qr canvas{width:100%!important;height:100%!important}.rule-title{display:inline-block;background:var(--main);color:#fff;border-radius:999px;font-size:9pt;font-weight:900;padding:1.2mm 4mm;margin:2mm 0}.rules{white-space:pre-line;text-align:left;font-size:6.6pt;line-height:1.34;width:100%}.back-qr{width:16mm;height:16mm;margin:1.5mm auto 0}.back-note{font-size:6.1pt;line-height:1.25;margin-top:1mm}.horizontal .front-grid{display:grid;grid-template-columns:23mm 1fr 19mm;gap:2.8mm;align-items:center;margin-top:1.2mm}.horizontal .photo{width:21mm;height:28mm;object-fit:cover;border:1px solid #94a3b8;border-radius:1.5mm}.horizontal .student-name{font-size:11pt;max-width:none}.horizontal .student-info{font-size:7.8pt}.horizontal .front-qr{width:17mm;height:17mm}.horizontal .school-head{justify-content:flex-start}.horizontal .school-name{max-width:62mm}.horizontal .rules{font-size:7.2pt;line-height:1.38}.horizontal .back-qr{width:18mm;height:18mm}.print-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(380px,1fr));gap:12mm 7mm;justify-items:center}.student-row{display:flex;gap:.6rem;align-items:center;padding:.