<script>
const BASE=<?=json_encode(BASE_URL)?>, YEAR=<?=json_encode($year)?>;
const sample={id:'sample',name:'NGUYỄN VĂN AN',code:'XM25010001',class_name:'10A1',dob:'2010-08-15',gender:'Nam',photo_url:'',verify_url:location.origin+BASE+'student_verify.php?id=sample&t=sample',public_code:'XM25010001'};
const defaults={type:'vertical',agency:'SỞ GD&ĐT TUYÊN QUANG',school:'TRƯỜNG PTDTNT THCS&THPT XÍN MẦN',title:'THẺ HỌC SINH',cohort:'2022 - 2025',main:'#0d47a1',second:'#42a5f5',accent:'#f4b400',theme:'blue',logo:'',rules:rulesInput.value,note:noteInput.value,showLogo:true,showAgency:true,showSchool:true,showTitle:true,showPhoto:true,showName:true,showClass:true,showYear:true,showCohort:true,frontQr:false,backRules:true,backQr:true,backNote:true};
let cfg=Object.assign({},defaults,JSON.parse(localStorage.getItem('cdsCardTemplateV2')||'{}')),loadedStudents=[];
const themes={blue:['#0d47a1','#42a5f5','#f4b400'],green:['#166534','#22c55e','#facc15'],red:['#991b1b','#ef4444','#f59e0b'],purple:['#6b21a8','#c026d3','#f0abfc'],orange:['#c2410c','#fb923c','#fde047'],teal:['#0f766e','#14b8a6','#67e8f9'],navy:['#0f2f57','#2d6ca2','#f4b400'],rose:['#9f1239','#fb7185','#fda4af']};
const fieldDefs=[['showLogo','Logo'],['showAgency','Sở GD&ĐT'],['showSchool','Tên trường'],['showTitle','Tiêu đề'],['showPhoto','Ảnh'],['showName','Tên HS'],['showClass','Lớp'],['showYear','Năm học'],['showCohort','Niên khóa'],['frontQr','QR mặt trước'],['backRules','Quy định mặt sau'],['backQr','QR mặt sau'],['backNote','Ghi chú QR']];
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function setColors(){document.documentElement.style.setProperty('--main',cfg.main);document.documentElement.style.setProperty('--second',cfg.second);document.documentElement.style.setProperty('--accent',cfg.accent)}
function syncInputs(){agencyInput.value=cfg.agency;schoolInput.value=cfg.school;titleInput.value=cfg.title;cohortInput.value=cfg.cohort;rulesInput.value=cfg.rules;noteInput.value=cfg.note;mainColor.value=cfg.main;secondColor.value=cfg.second;accentColor.value=cfg.accent;document.querySelectorAll('.type-card').forEach(x=>x.classList.toggle('active',x.dataset.type===cfg.type));fieldOptions.innerHTML=fieldDefs.map(([k,l])=>`<label class="col-6 form-check small"><input class="form-check-input field-toggle" data-key="${k}" type="checkbox" ${cfg[k]?'checked':''}><span class="form-check-label">${l}</span></label>`).join('');themeGrid.innerHTML='';Object.entries(themes).forEach(([k,v])=>{let b=document.createElement('button');b.type='button';b.className='theme'+(cfg.theme===k?' active':'');b.dataset.theme=k;b.style.background=`linear-gradient(135deg,${v[0]} 0 46%,${v[1]} 46% 75%,${v[2]} 75%)`;themeGrid.appendChild(b)});sizeLabel.textContent=cfg.type==='vertical'?'Dọc: cao 86 mm × rộng 54 mm':'Ngang: cao 60 mm × rộng 90 mm';setColors()}
function photoHtml(s,cls){let src=s.photo_url||'';return src?`<img class="photo" src="${esc(src)}" onerror="this.outerHTML='<div class=\'photo d-flex align-items-center justify-content-center bg-light\'><i class=\'bi bi-person fs-2 text-secondary\'></i></div>'">`:`<div class="photo d-flex align-items-center justify-content-center bg-light"><i class="bi bi-person fs-2 text-secondary"></i></div>`}
function headerHtml(){return `<div class="school-head">${cfg.showLogo?(cfg.logo?`<img class="logo" src="${cfg.logo}">`:'<div class="logo d-flex align-items-center justify-content-center"><i class="bi bi-building fs-4"></i></div>'):''}<div class="school-lines">${cfg.showAgency?`<div class="agency">${esc(cfg.agency)}</div>`:''}${cfg.showSchool?`<div class="school-name">${esc(cfg.school)}</div>`:''}</div></div>`}
function infoHtml(s){return `<div class="student-info">${cfg.showClass?`<div>Lớp: <b>${esc(s.class_name||'—')}</b></div>`:''}${cfg.showYear?`<div>Năm học: <b>${esc(YEAR)}</b></div>`:''}${cfg.showCohort?`<div>Niên khóa: <b>${esc(cfg.cohort)}</b></div>`:''}</div>`}
function frontFace(s){let vertical=cfg.type==='vertical';return `<section class="card-face ${cfg.type} front"><div class="decor-top"></div><div class="decor-bottom"></div><div class="face-content">${headerHtml()}${cfg.showTitle?`<div class="title">${esc(cfg.title)}</div>`:''}${vertical?`${cfg.showPhoto?photoHtml(s):''}${cfg.showName?`<div class="student-name">${esc(s.name)}</div>`:''}${infoHtml(s)}${cfg.frontQr?`<div class="front-qr qr" data-url="${esc(s.verify_url)}"></div>`:''}`:`<div class="front-grid"><div>${cfg.showPhoto?photoHtml(s):''}</div><div>${cfg.showName?`<div class="student-name">${esc(s.name)}</div>`:''}${infoHtml(s)}</div>${cfg.frontQr?`<div class="front-qr qr" data-url="${esc(s.verify_url)}"></div>`:'<div></div>'}</div>`}</div></section>`}
function backFace(s){return `<section class="card-face ${cfg.type} back"><div class="decor-top"></div><div class="decor-bottom"></div><div class="face-content">${cfg.backRules?`<div class="rule-title">QUY ĐỊNH SỬ DỤNG THẺ</div><div class="rules">${esc(cfg.rules)}</div>`:''}${cfg.backQr?`<div class="back-qr qr" data-url="${esc(s.verify_url)}"></div>`:''}${cfg.backNote?`<div class="back-note">${esc(cfg.note)}</div>`:''}</div></section>`}
function cardSet(s){return `<article class="fold-set">${frontFace(s)}<div class="fold-line"></div>${backFace(s)}</article>`}
function makeQr(root){root.querySelectorAll('.qr').forEach(el=>{el.innerHTML='';if(typeof QRCode!=='undefined')new QRCode(el,{text:el.dataset.url,width:100,height:100,correctLevel:QRCode.CorrectLevel.M})})}
function renderSample(){samplePreview.innerHTML=cardSet(sample);makeQr(samplePreview)}
function readCfg(){cfg.agency=agencyInput.value.trim();cfg.school=schoolInput.value.trim();cfg.title=titleInput.value.trim();cfg.cohort=cohortInput.value.trim();cfg.rules=rulesInput.value;cfg.note=noteInput.value;cfg.main=mainColor.value;cfg.second=secondColor.value;cfg.accent=accentColor.value;document.querySelectorAll('.field-toggle').forEach(x=>cfg[x.dataset.key]=x.checked);setColors();renderSample()}
document.querySelectorAll('.type-card').forEach(x=>x.onclick=()=>{cfg.type=x.dataset.type;syncInputs();renderSample()});themeGrid.addEventListener('click',e=>{let b=e.target.closest('.theme');if(!b)return;cfg.theme=b.dataset.theme;[cfg.main,cfg.second,cfg.accent]=themes[cfg.theme];syncInputs();renderSample()});[agencyInput,schoolInput,titleInput,cohortInput,rulesInput,noteInput,mainColor,secondColor,accentColor].forEach(x=>x.addEventListener('input',readCfg));fieldOptions.addEventListener('change',readCfg);logoInput.onchange=function(){let f=this.files&&this.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{cfg.logo=r.result;renderSample()};r.readAsDataURL(f)};
function showStep(step){designStep.classList.toggle('hidden',step!=='design');printStep.classList.toggle('hidden',step!=='print');document.querySelectorAll('.step-btn').forEach(x=>x.classList.toggle('active',x.dataset.step===step))}
document.querySelectorAll('.step-btn').forEach(x=>x.onclick=()=>showStep(x.dataset.step));saveTemplate.onclick=()=>{readCfg();localStorage.setItem('cdsCardTemplateV2',JSON.stringify(cfg));showStep('print');window.scrollTo({top:0,behavior:'smooth'})};resetTemplate.onclick=()=>{if(!confirm('Khôi phục mẫu mặc định?'))return;cfg=Object.assign({},defaults);syncInputs();renderSample()};
gradeFilter.onchange=()=>{let g=gradeFilter.value;[...classFilter.options].forEach((o,i)=>{if(i===0)return;o.hidden=!!g&&o.dataset.grade!==g});if(classFilter.selectedOptions[0]?.hidden)classFilter.value=''};
async function loadStudentData(){loadStatus.textContent='Đang tải học sinh...';studentResults.innerHTML='';printPreview.innerHTML='';selectedCount.textContent='0';let p=new URLSearchParams({grade:gradeFilter.value,class:classFilter.value,q:searchFilter.value.trim(),photo:photoFilter.value,limit:'1000'});try{let res=await fetch(BASE+'student_card_students.php?'+p.toString(),{credentials:'same-origin'});let data=await res.json();if(!data.ok)throw new Error(data.message||'Không tải được dữ liệu');loadedStudents=data.students||[];loadStatus.textContent=`Đã tải ${loadedStudents.length} học sinh.`;studentResults.innerHTML=loadedStudents.map(s=>`<label class="student-row"><input class="form-check-input print-student" type="checkbox" value="${esc(s.id)}"><img src="${esc(s.photo_url)}" onerror="this.style.visibility='hidden'"><span><strong>${esc(s.name)}</strong><small class="d-block text-muted">${esc(s.class_name)} · ${esc(s.code||s.public_code)} ${s.has_photo?'· Có ảnh':'· Chưa ảnh'}</small></span></label>`).join('')||'<div class="text-muted py-3">Không có học sinh phù hợp.</div>'}catch(err){loadStatus.textContent='Lỗi: '+err.message;loadedStudents=[]}}
loadStudents.onclick=loadStudentData;searchFilter.addEventListener('keydown',e=>{if(e.key==='Enter')loadStudentData()});selectAll.onclick=()=>{document.querySelectorAll('.print-student').forEach(x=>x.checked=true);renderSelected()};clearAll.onclick=()=>{document.querySelectorAll('.print-student').forEach(x=>x.checked=false);renderSelected()};studentResults.addEventListener('change',renderSelected);
function renderSelected(){let ids=new Set([...document.querySelectorAll('.print-student:checked')].map(x=>x.value));let rows=loadedStudents.filter(s=>ids.has(String(s.id)));selectedCount.textContent=rows.length;printPreview.innerHTML=rows.map(cardSet).join('');makeQr(printPreview)}
printCards.onclick=()=>{if(!document.querySelector('.print-student:checked')){alert('Hãy chọn ít nhất một học sinh.');return}renderSelected();setTimeout(()=>window.print(),120)};
syncInputs();renderSample();showStep('design');
</script>
</body>
</html>
